// spec: specs/contact-login-return.md (1.5, 1.6) · кейс: .qa/tests/contact-login-return/CONTACT-AUTH-05.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение (запись заблокирована), вход не выполняется.
// Адрес …&contact=1 — тот, на который сайт возвращает после входа из попапа связи (redirectAfterLogin, кейсы 01/02).
import { test, expect, Page } from '@playwright/test';
import { prepareGuest, LISTING_URL, LOAD } from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

const CONTACT_URL = `${LISTING_URL}&contact=1`;
/** Удержание карточки связи по PR #166 — до 3 с; проверяем с запасом после 4 с от начала загрузки страницы. */
const AFTER_HOLD_MS = 4000;

const whatsappButton = (page: Page) => page.locator('button').filter({ hasText: /^\s*WhatsApp\s*$/ }).first();
const inViewportNow = (page: Page) =>
  whatsappButton(page).evaluate((el) => {
    const r = el.getBoundingClientRect();
    return r.height > 0 && r.top >= 0 && r.bottom <= window.innerHeight;
  });
/** Дождаться момента «≥ ms от начала навигации» по часам страницы (требование «через 3 с» из кейса). */
const pageTimeAtLeast = (page: Page, ms: number) =>
  page.waitForFunction((t) => performance.now() >= t, ms, { timeout: ms + LOAD.timeout });

test.describe('Связь с владельцем — возврат после входа из попапа', () => {
  test('contact=1: кнопка связи в экране сразу и после удержания (3 с) #083d10 @android @prod-safe', async ({ page }) => {
    await prepareGuest(page);
    await page.goto(CONTACT_URL, { waitUntil: 'commit' });

    const wa = whatsappButton(page);
    await wa.waitFor({ state: 'attached', timeout: LOAD.timeout });
    await expect(wa, 'кнопка WhatsApp в экране сразу после появления').toBeInViewport({ ratio: 1, timeout: 2000 });
    expect(await page.evaluate(() => window.scrollY), 'страница прокручена к зоне связи').toBeGreaterThan(0);

    await pageTimeAtLeast(page, AFTER_HOLD_MS);
    expect(await inViewportNow(page), 'кнопка WhatsApp в экране после 3 с (удержание закончилось)').toBe(true);
  });

  test('contact=1: после ручной прокрутки страница не возвращается к кнопке связи #083d10 @android @prod-safe', async ({ page }) => {
    await prepareGuest(page);
    await page.goto(CONTACT_URL, { waitUntil: 'commit' });

    const wa = whatsappButton(page);
    await wa.waitFor({ state: 'attached', timeout: LOAD.timeout });
    await expect(wa).toBeInViewport({ ratio: 1, timeout: 2000 });
    const yBefore = await page.evaluate(() => window.scrollY);
    expect(yBefore, 'страница прокручена к зоне связи (есть куда прокрутить вверх)').toBeGreaterThan(100);

    await page.mouse.move(200, 400);
    await page.mouse.wheel(0, -500);
    await page.waitForFunction((y) => window.scrollY < y - 100, yBefore, { timeout: 3000 });
    const scrolledAt = await page.evaluate(() => Math.round(performance.now()));
    test.info().annotations.push({ type: 'manual-scroll-at-ms', description: String(scrolledAt) });

    await pageTimeAtLeast(page, AFTER_HOLD_MS);
    const yAfter = await page.evaluate(() => window.scrollY);
    expect(yAfter, 'после ручной прокрутки вверх страница не вернулась к кнопке связи').toBeLessThan(yBefore - 100);
  });
});
